void Solver::bump_var(int var, double coeff) {
    // Use a non-linear bump: scale coeff by a factor based on current activity
    // to give extra boost to highly active variables (momentum-like effect)
    double bonus = coeff * var_inc;
    // Apply additional boost if this variable has been recently active
    if (activity[var] > var_inc * 0.5) {
        bonus *= 1.05;
    }
    if ((activity[var] += bonus) > 1e100) {
        for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
